                http_code: Some(418),
                error_code: Some("NotARealError".to_string()),
                error_message: Some("This error is made up.".to_string()),
            },
            error_code: Some(MOUNTPOINT_ERROR_CLIENT.to_string()),
            s3_bucket_name: Some(bucket.to_string()),
